-- 称号を足す: プロトコルの習熟度 6 の称号 (m_ + プロトコル名) 30 個
alter table public.secure_rooms drop constraint if exists secure_rooms_host_badge_check;
alter table public.secure_rooms drop constraint if exists secure_rooms_guest_badge_check;
alter table public.secure_rooms
  add constraint secure_rooms_host_badge_check check (host_badge is null or host_badge in ('compiler','veteran','tactician','expert','architect','master','legend','ascended','underdog','chainer','flawless','grandmaster','platinum','puzzler','compuzzler','gambler','highroller','fortune','regular','weeklylegend','m_darkness','m_death','m_fire','m_gravity','m_life','m_light','m_metal','m_plague','m_psychic','m_speed','m_spirit','m_water','m_apathy','m_hate','m_love','m_chaos','m_clarity','m_corruption','m_courage','m_fear','m_ice','m_luck','m_mirror','m_peace','m_smoke','m_time','m_war','m_assimilation','m_diversity','m_unity')),
  add constraint secure_rooms_guest_badge_check check (guest_badge is null or guest_badge in ('compiler','veteran','tactician','expert','architect','master','legend','ascended','underdog','chainer','flawless','grandmaster','platinum','puzzler','compuzzler','gambler','highroller','fortune','regular','weeklylegend','m_darkness','m_death','m_fire','m_gravity','m_life','m_light','m_metal','m_plague','m_psychic','m_speed','m_spirit','m_water','m_apathy','m_hate','m_love','m_chaos','m_clarity','m_corruption','m_courage','m_fear','m_ice','m_luck','m_mirror','m_peace','m_smoke','m_time','m_war','m_assimilation','m_diversity','m_unity'));
